(function(){
'use strict';
const D=window.DecisionData,E=window.DecisionEngine,$=id=>document.getElementById(id),key='itaso-decisiones-v1';
let state=E.fresh();
try{state=E.restore(localStorage.getItem(key));}catch{$('storage-note').hidden=false;}
let day=E.activeDay(state),period=state.days[day].findIndex(n=>n===null),view='play',previousView='play';
if(period<0)period=2;
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{$('storage-note').hidden=false;}}
function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
function focus(id){$(id).focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});}
function show(name){view=name;for(const n of ['play','end','history'])$(n+'-view').hidden=n!==name;$('juego').classList.toggle('is-history',name==='history');}
function points(value){return (value>0?'+':'')+value+' pts';}
function meter(id,value){const node=$(id);node.setAttribute('aria-valuenow',value);node.setAttribute('aria-valuetext',points(value)+', de −45 a +45; cada día empieza en 0');const fill=node.querySelector('.meter-fill');fill.style.height=(Math.abs(value)/45*50)+'%';fill.style.bottom=value>=0?'50%':(50-Math.abs(value)/45*50)+'%';fill.style.background=value>0?'#00a259':'#e63832';}
function renderFeedback(option){$('feedback').hidden=!option;if(!option)return;$('feedback-title').textContent=option.points>0?'¡Esta elección suma!':'Podemos elegir algo distinto';$('delta').textContent=(option.points>0?'+':'')+option.points+' puntos';$('explanation').textContent=option.message;$('continue').textContent=E.completed(state,day)?'Ver el final del día':'Continuar a '+D.periods[state.days[day].findIndex(n=>n===null)].toLowerCase();}
function renderPlay(moveFocus=false){show('play');$('day-label').textContent=D.days[day]+' · '+D.periods[period]+' · '+(state.days[day].filter(n=>n!==null).length)+'/3 decisiones';$('question').textContent=D.questions[day][period].prompt;
 document.querySelectorAll('[data-period]').forEach(b=>{const p=Number(b.dataset.period);b.setAttribute('aria-pressed',String(p===period));b.classList.toggle('done',state.days[day][p]!==null);});
 const selected=state.days[day][period];$('options').replaceChildren();$('options').classList.toggle('answered',selected!==null);
 D.questions[day][period].options.forEach((option,index)=>{const button=el('button',option.text,'option');button.disabled=selected!==null;button.setAttribute('aria-pressed',String(selected===index));button.addEventListener('click',()=>{if(!E.choose(state,day,period,index))return;save();renderPlay();$('continue').focus({preventScroll:true});$('feedback').scrollIntoView({block:'nearest',behavior:'instant'});});$('options').append(button);});
 renderFeedback(selected===null?null:D.questions[day][period].options[selected]);const value=E.score(state,day);meter('play-meter',value);$('meter-value').textContent=points(value);renderShortcuts();if(moveFocus)focus('question-title');
}
function renderShortcuts(){const box=$('week-shortcuts');box.replaceChildren();D.days.forEach((label,i)=>{const b=el('button',D.shortDays[i],'day-button');const done=E.completed(state,i);b.setAttribute('aria-label','Ver '+label+(done?', completado':state.days[i].some(n=>n!==null)?', en curso':', sin decisiones'));if(i===day)b.setAttribute('aria-current','date');b.classList.toggle('completed',done);b.addEventListener('click',()=>openHistory(i));box.append(b);});const count=state.days.filter((_,i)=>E.completed(state,i)).length;$('progress-copy').textContent=count+' de 7 días completados · Toca un día para ver tus decisiones.';}
function renderEnd(moveFocus=true){show('end');const value=E.score(state,day),feeling=E.feeling(value);$('end-day').textContent=D.days[day]+' · 3 de 3 decisiones';$('end-title').textContent=day===6?'¡Completaste la semana!':'¡Terminó el día!';$('end-face').src='assets/'+feeling.face+'.svg';$('end-feeling').textContent=feeling.title;$('end-message').textContent=feeling.message;$('end-score').textContent='Puntos del día: '+points(value);$('end-decisions').replaceChildren();D.periods.forEach((name,p)=>{const a=el('article');const option=D.questions[day][p].options[state.days[day][p]];a.append(el('h3',name),el('p',option.text),el('strong',points(option.points)));$('end-decisions').append(a);});$('next-day').textContent=day===6?'Volver a jugar':'Jugar el '+D.days[day+1].toLowerCase();if(moveFocus)focus('end-title');}
function openHistory(index){if(view!=='history')previousView=view;show('history');$('history-title').textContent=D.days[index];$('day-tile').textContent=D.shortDays[index];const count=state.days[index].filter(n=>n!==null).length;$('history-status').textContent=(count?'Total del día: '+points(E.score(state,index))+' · ':'')+(count===3?'Día completado · Tus decisiones':count?count+' de 3 decisiones · Día en curso':'Aún no has jugado este día');$('week-total').textContent='Total de la semana: '+points(state.days.reduce((sum,_,d)=>sum+E.score(state,d),0));$('history-periods').replaceChildren();D.periods.forEach((name,p)=>{const card=el('section',undefined,'history-period');card.append(el('h2',name));const n=state.days[index][p];if(n===null)card.append(el('p','Todavía no hay una decisión para este momento.'));else{const option=D.questions[index][p].options[n];card.append(el('p',option.text),el('p',(option.points>0?'+':'')+option.points+' puntos','effect'));const details=el('details');details.append(el('summary','Por qué'),el('p',option.message));card.append(details);}$('history-periods').append(card);});const value=E.score(state,index);meter('history-meter',value);$('history-value').textContent=count?points(value):'Sin jugar';$('history-days').replaceChildren();D.days.forEach((name,i)=>{if(i===index)return;const b=el('button',name,'history-day');b.append(el('small',E.completed(state,i)?points(E.score(state,i))+' · Completado':state.days[i].some(n=>n!==null)?points(E.score(state,i))+' · En curso':'Sin jugar'));b.addEventListener('click',()=>openHistory(i));$('history-days').append(b);});focus('history-title');}
$('continue').addEventListener('click',()=>{if(E.completed(state,day))renderEnd();else{period=state.days[day].findIndex(n=>n===null);renderPlay(true);}});
document.querySelectorAll('[data-period]').forEach(b=>b.addEventListener('click',()=>{period=Number(b.dataset.period);renderPlay(true);}));
$('next-day').addEventListener('click',()=>{if(day===6){$('reset-dialog').showModal();return;}day++;period=0;renderPlay(true);});
$('see-week').addEventListener('click',()=>openHistory(day));$('back-game').addEventListener('click',()=>{if(previousView==='end'&&E.completed(state,day))renderEnd();else renderPlay(true);});
for(const id of ['learn-nav','discover'])$(id).addEventListener('click',()=>$('learn-dialog').showModal());document.querySelector('.close-dialog').addEventListener('click',()=>$('learn-dialog').close());$('reset-week').addEventListener('click',()=>$('reset-dialog').showModal());$('cancel-reset').addEventListener('click',()=>$('reset-dialog').close());$('confirm-reset').addEventListener('click',()=>{state=E.fresh();day=0;period=0;save();$('reset-dialog').close();renderPlay(true);});
const navigation=window.ITASO_CONFIG?.navigation||{};for(const label of document.querySelectorAll('[data-nav]')){const href=navigation[label.dataset.nav];if(!href)continue;try{const url=new URL(href,location.href);if(!['https:','http:'].includes(url.protocol))continue;const link=el('a',label.textContent,label.className);link.href=url.href;label.replaceWith(link);}catch{}}
if(E.completed(state,day))renderEnd(false);else renderPlay();
})();
